      if (lookahead == ',') ADVANCE(15);
      if (lookahead == '-') ADVANCE(21);
      if (lookahead == '/') ADVANCE(2);
      if (lookahead == '=') ADVANCE(16);
      if (lookahead == '}') ADVANCE(14);
